import type { HTMLAttributes, ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './list.module.scss'

export interface ListProps extends HTMLAttributes<HTMLUListElement> {}

/** Bordered list container for settings rows, activity and pickers. */
export function List({ className, ...props }: ListProps) {
  return <ul className={cx(styles.root, className)} {...props} />
}

export interface ListItemProps
  extends Omit<HTMLAttributes<HTMLLIElement>, 'title'> {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  trailing?: ReactNode
  href?: string
}

export function ListItem({
  icon,
  title,
  description,
  trailing,
  href,
  className,
  ...props
}: ListItemProps) {
  const content = (
    <>
      {icon ? <span className={styles.icon}>{icon}</span> : null}
      <span className={styles.content}>
        <span className={styles.title}>{title}</span>
        {description ? (
          <span className={styles.description}>{description}</span>
        ) : null}
      </span>
      {trailing ? <span className={styles.trailing}>{trailing}</span> : null}
    </>
  )

  if (href) {
    return (
      <li>
        <a href={href} className={cx(styles.item, className)}>
          {content}
        </a>
      </li>
    )
  }

  return (
    <li className={cx(styles.item, className)} {...props}>
      {content}
    </li>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
}

.item {
  display: flex;
  align-items: flex-start;
  gap: vz.space(3);
  padding: vz.space(3.5) vz.space(4);
  border-bottom: 1px solid vz.color('border', 0.7);
  color: inherit;
  text-decoration: none;
  transition: background-color vz.duration('fast') vz.ease('out');

  &:last-child {
    border-bottom: 0;
  }

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, -2px, 0.6);
}

.icon {
  display: inline-flex;
  width: vz.space(9);
  height: vz.space(9);
  flex: none;
  align-items: center;
  justify-content: center;
  border-radius: vz.radius('md');
  background: vz.color('accent');
  color: vz.color('accent-foreground');

  svg {
    @include vz.icon(4);
  }
}

.content {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 2px;
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.5;
}

.trailing {
  flex: none;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}
